import{_ as o,o as r,c as t,a7 as i}from"./chunks/framework.FWlv_suP.js";const h=JSON.parse('{"title":"Office Orbit Support","description":"Official support information for Office Orbit.","frontmatter":{"title":"Office Orbit Support","description":"Official support information for Office Orbit.","navbar":false,"sidebar":false,"aside":false,"outline":false,"footer":false,"prev":false,"next":false,"editLink":false,"lastUpdated":false,"pageClass":"standalone-policy"},"headers":[],"relativePath":"support/office-orbit.md","filePath":"support/office-orbit.md"}'),a={name:"support/office-orbit.md"};function s(n,e,l,c,f,p){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="office-orbit-support" tabindex="-1">Office Orbit Support <a class="header-anchor" href="#office-orbit-support" aria-label="Permalink to &quot;Office Orbit Support&quot;">​</a></h1><p>For Office Orbit support, email <strong><a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></strong>.</p><p>Include the app version, Android or browser version, device model, affected screen, and safe reproduction steps. Do not email workplace secrets, passwords, access tokens, PINs, biometric information, confidential JIRA or work-log content, or unredacted reports.</p><h2 id="common-help" tabindex="-1">Common help <a class="header-anchor" href="#common-help" aria-label="Permalink to &quot;Common help&quot;">​</a></h2><ul><li><strong>Sign-in fails:</strong> confirm internet access, verify the password, and check that the Office Orbit API is available.</li><li><strong>An active session cannot be restored:</strong> reconnect and sign in again if the session has expired or the API rejects it.</li><li><strong>PIN or biometric unlock fails:</strong> use the PIN and confirm Android has a supported enrolled biometric. If the PIN is forgotten, clearing app storage removes the local lock, settings, and saved session.</li><li><strong>Work data is missing:</strong> refresh the screen and confirm that you are authorized to view the relevant source records.</li><li><strong>PDF export fails:</strong> retry with a smaller date range and choose an available Android save/share destination or browser download location.</li><li><strong>A work link will not open:</strong> check the URL, connection, and destination service availability.</li></ul><p>Office Orbit is not released on Google Play. Use the official browser version or a project release supplied by the developer.</p>',6)])])}const m=o(a,[["render",s]]);export{h as __pageData,m as default};
